import React, { useMemo } from 'react';
import dynamic from 'next/dynamic';

import { Layout } from 'antd';

import MainHoc from 'components/IntegratePages/integrationHoc';
import { FeatureFlagsProvider } from 'uxcam-frontend-components';
import ReactLoader from '../common/reactLoading';

// override flag params for welcome screen
const FeatureFlagParams = {
  applicationId: 'new-registration',
  anonymous: false, // override the default value of true
  key: 'anonymous-user', // prevent individual user tracking
}

const CreateOrganization = dynamic(
  import('components/features/setting/OrganizationSetting/createOrganization'),
  {
    loading: () => <ReactLoader fullscreen />,
  }
);
const DashboardAccess = dynamic(import('../common/dashboardAccess'), {
  loading: () => <ReactLoader fullscreen />,
});
const ErrorPage = dynamic(import('../common/error'), {
  loading: () => <p />,
});
const WelcomeMessage = dynamic(import('./integrationInfo/welcomeMessage'), {
  loading: () => <ReactLoader fullscreen />,
});
const { Content } = Layout;
const Dashboard = ({
  orgForm,
  appForm,
  resetStatus,
  errorReducer,
  changeAppStatus,
  checkOrgAppPage,
  dashboardAccessView,
  reasonNoDashboardAccess,
}) => {

  const [ featureFlagParams, setFeatureFlagParams ] = React.useState(FeatureFlagParams)

  React.useEffect( () => {
    let tryNewSignup = ''
    try {
      tryNewSignup = sessionStorage.getItem('tryNewSignup')
    } catch (err) {
      // silent fail
    }
    if ( tryNewSignup ) {
      setFeatureFlagParams( ( prev ) => {
        return {
          ...prev,
          // @note: Vale requested to try the feature flag on prod, without enabling the feature flag
          tryNewSignup: true
        }
      } )
    }
  }, [] )

  const handleDashboard = useMemo(() => {
    if (errorReducer?.status && errorReducer?.pos === 'dashboard') {
      return <ErrorPage error={errorReducer} />;
    }
    if (!orgForm && !appForm) {
      return <ReactLoader fullscreen />;
    }
    return (
      <div>
        {!dashboardAccessView && orgForm && (
          <CreateOrganization
            changeAppStatus={changeAppStatus}
            checkOrgAppPage={checkOrgAppPage}
          />
        )}
        {appForm && !dashboardAccessView && (
          <FeatureFlagsProvider user={featureFlagParams} clientKey={process.env.FEATURE_FLAG_ID}>
            <WelcomeMessage resetStatus={resetStatus} />
          </FeatureFlagsProvider>
        )}
      </div>
    );
  }, [appForm, changeAppStatus, checkOrgAppPage, dashboardAccessView, errorReducer, orgForm, resetStatus, featureFlagParams]);

  if (dashboardAccessView) {
    return (
      <DashboardAccess reasonNoDashboardAccess={reasonNoDashboardAccess} />
    );
  }
  return (
    <Content style={{ padding: '0px 16px 0', overflow: 'initial', backgroundColor: '#f5f5f5' }}>
      {handleDashboard}
    </Content>
  );
};
export default MainHoc(Dashboard);
