import React from 'react';
import Router from 'next/router';
import {
  changeUrl,
} from 'redux/actions/common'
import CommonApi from 'services/commonApi';
import Layout from 'components/IntegratePages/layout';
import Dashboard from 'components/IntegratePages/MainDashboard';

const Page = (props) => <Dashboard {...props} />
Page.layout = Layout
Page.getInitialProps = async ({ store, req, res, query }) => {
  if (query) {
    if (query.url?.split('?')[0] === '/dashboard' && query.parentType !== 'shortUrl') query.parentType = 'dashboard'
    store.dispatch(changeUrl(query))
  }

  if (query.parentType === 'shortUrl') {
    const data = await CommonApi.getOriginalUrl(query.id, query.type, query?.appId)
    let redirectUrl;

    if (data?.data) {
      if (query.type === 'r' || query.type === 's') {
        redirectUrl = `/app/${data.data.appId}/aisession/${data.data.sessionId}?secondarysessionid=${data.data.sessionId}`;
      } else {
        redirectUrl = `/app/${data.data.appId}/user/${data.data.uxcamUserId}`;
      }
    } else if (data?.response) {
      const status = data.response.data?.error?.status || data.response.status;
      if (status === 401 || status === 403) {
        // Logged out: send them to login carrying this short url, so resolving it
        // is retried after auth instead of dead-ending on a generic error page.
        const shortUrlPath = `/dashboard?type=${query.type}&parentType=shortUrl${
          query.appId ? `&appId=${query.appId}` : ''
        }&id=${query.id}`;
        redirectUrl = `/login?redirect=${encodeURIComponent(shortUrlPath)}`;
      } else {
        const message = data.response.data?.error?.message;
        redirectUrl = `/error?errorStatus=${status}${message ? `&errorMessage=${encodeURIComponent(message)}` : ''}`;
      }
    } else {
      // No HTTP response at all (network error, timeout, interceptor failure).
      // Falling through to the plain dashboard leaves the user on an endless loader.
      redirectUrl = '/error?errorStatus=503';
    }

    if (req && res) {
      return res.redirect(redirectUrl);
    }
    Router.replace(redirectUrl);
    return { query };
  }

  return { query }
}
export default Page
